#include <iostream>
#include <memory>
#include <string>

class Resource {
public:
    explicit Resource(int id) : id_{id} {
        std::cout << "Resource " << id_ << " created" << std::endl;
    }
    ~Resource() {
        std::cout << "Resource " << id_ << " destroyed" << std::endl;
    }
    void performAction() const {
        std::cout << "Resource " << id_ << " action performed" << std::endl;
    }
private:
    int id_;
};

void runTask(bool triggerError) {
    std::cout << "Starting runTask" << std::endl;
    std::unique_ptr<Resource> singlePtr(new Resource(42));
    singlePtr->performAction();

    std::unique_ptr<std::string[]> arrayPtr(new std::string[2]);
    arrayPtr[0] = "Hello";
    arrayPtr[1] = "unique_ptr";
    std::cout << arrayPtr[0] << " " << arrayPtr[1] << std::endl;

    if (triggerError) {
        std::cout << "Triggering error..." << std::endl;
        throw std::runtime_error("Task failed prematurely");
    }
    std::cout << "Finished runTask successfully" << std::endl;
}

int main() {
    try {
        runTask(true);
    } catch (const std::exception& ex) {
        std::cout << "Caught in main: " << ex.what() << std::endl;
    }
    return 0;
}

#include <iostream>
#include <stdexcept>

void triggerError(int code) {
    if (code == 1) {
        throw std::out_of_range("Index out of range error");
    } else if (code == 2) {
        throw std::underflow_error("Arithmetic underflow occurred");
    } else if (code == 3) {
        throw 500; // Throwing primitive int
    }
}

int main() {
    for (int test = 1; test <= 3; ++test) {
        try {
            triggerError(test);
        }
        // Derived-class handler must precede base-class handler
        catch (const std::out_of_range& ex) {
            std::cout << "Test " << test << " caught out_of_range: " << ex.what() << std::endl;
        }
        catch (const std::logic_error& ex) {
            std::cout << "Test " << test << " caught logic_error: " << ex.what() << std::endl;
        }
        catch (const std::exception& ex) {
            std::cout << "Test " << test << " caught standard exception: " << ex.what() << std::endl;
        }
        catch (...) {
            std::cout << "Test " << test << " caught unknown non-standard exception" << std::endl;
        }
    }
    return 0;
}
